"""Crestline v2 case study — part 3: writing, review, gallery, handoff, next, assembly."""
from cs2 import *
import re, pathlib
# ───────── 12 UX writing
def writing():
    voice=tbl(["Concept","What it sounds like","Do","Don't"],[["<b>Plain</b>","Everyday words. Explain a term once, then use it.","Use shares, not scrips. Say what a number includes.","Use jargon such as RMS, MTM or freeze limit without explaining."],["<b>Calm</b>","Steady and unhurried, even when the market is not.","Say Order placed. State the next step.","Use exclamation marks, urgency or celebration around money."],["<b>Honest</b>","States cost, risk and limits before the tap.","Show total required including charges. Say returns are not guaranteed.","Hide fees, imply certainty or pressure people to act."]])
    tone=tbl(["Situation","Tone","Example"],[["Error or rejection","Empathetic, solution first","Not enough funds. You need ₹1,46,090 more. Add money and try again."],["High-stakes action","Serious and transparent","Sell 12 TCS shares at market price? This cannot be undone once filled."],["Success","Brief and proportional","Order placed. We will tell you when it fills."],["First use","Patient, short steps","Add money to start. It takes about a minute."],["Empty state","Hopeful, one next step","No open orders. Orders you place show here until they fill."]])
    ba=[["Waiting","Waiting for a seller at ₹3,410.00","The status now says what it is waiting for."],["Closing soon","Closes 30 Oct","A date beats a vague phrase."],["Next —","No next date. SIP is paused.","A dash tells people nothing."],["Square off all","Close all positions","Square off is jargon."],["Convert","Convert to delivery","Say what it converts to."],["RMS: Insufficient margin","Not enough funds. You need ₹1,46,090 more.","Plain cause plus the exact gap."],["Order cancelled by exchange","The price was outside today's allowed range (₹3,045.50 to ₹3,722.30). Change the price and try again.","Explains why and what to do."],["Sale proceeds from today's trades can be withdrawn after settlement.","Money from today's sales can be withdrawn after settlement, usually the next working day.","Active, specific, a time frame."],["Error 403","You do not have access to this. Sign in again or contact support.","No codes without meaning."],["Submit","Place 3 orders","Verb plus object, and the count."],["Are you sure?","Cancel this order? You will keep your funds.","Say what happens."],["Something went wrong","We could not load prices. Check your connection and try again.","Name the problem and the fix."]]
    ba_t=tbl(["Before","After","Why"],[[f'<span class="num" style="font-weight:600;color:var(--dn)">{a}</span>',f'<b>{b}</b>',c] for a,b,c in ba])
    rules=tbl(["Rule","Applies to","Example"],[["Title case","Screen titles, dialogs, navigation","Margin Calculator, Refer a Friend"],["Sentence case","Buttons, descriptions, helper text, errors, tooltips","Place 3 orders"],["Verb plus object","Buttons and links","Download statement, Set alert"],["Avoid","Generic labels","OK, Submit, Click here"],["Numerals","All quantities and amounts","12 shares, ₹40,920.00"],["Indian number format","Currency","₹1,03,255.60 (lakh and crore grouping)"],["Dates","No ordinal suffixes, month spelled out","5 Nov, 28 October 2026"],["Past tense","Status messages","Order placed, Funds added"],["Length","Buttons 2 to 4 words, titles 3 to 6, errors 12 to 18 words","Not enough funds. Add money and try again."],["Reading level","General audience, grade 7 to 8","Short sentences, 8 to 14 words"]])
    gl=tbl(["Term","We say","Meaning in one line"],[["Holdings","Holdings","Shares you own and keep for more than a day."],["Positions","Positions","Trades opened today that are still open."],["Order vs trade","Order, Trade","An order is a request. A trade is when it fills."],["Margin","Margin","Money set aside to cover a trade."],["Pledge","Pledge shares","Use shares you own as margin without selling them."],["Ex-date","Ex-dividend date","Hold before this date to receive the dividend."],["GTT","GTT, good till triggered","An order that waits for a price you choose."]])
    errs='<h3>Error and empty-state patterns</h3>'+tbl(["Type","Pattern","Example"],[["Validation","[Field] [requirement]","PAN must be 10 characters"],["System","[What failed]. [Cause]. [Recovery].","Order not placed. Your connection dropped. Check it and try again."],["Blocking","[What is blocked]. [Why]. [Action].","Update needed. This version is no longer supported. Update the app to continue."],["Permission","[Benefit]. [Permission].","Get an alert when a price hits your target. Allow notifications."],["Empty","[Why empty]. [Next step].","No alerts yet. Set one from any stock."]])
    return sec("12","writing","UX writing","A voice, a tone map, rules and twelve before and after rewrites. Written with the UX-writing standards: purposeful, concise, conversational, clear.",'<h3>Voice</h3>'+voice+'<h3>Tone by situation</h3>'+tone+'<h3>Before and after</h3>'+ba_t+'<h3>Style rules</h3>'+rules+'<h3>Glossary</h3>'+gl+errs+note("Accessibility: every icon has a text label or accessible name. Gain and loss always show a sign or arrow, never colour alone. Link text names its destination.","b"))
# ───────── 13 design review
def review():
    F=[("P0","A11y","All screens, secondary text","Grey secondary text (#8B9098) is 2.94:1 on paper and 3.21:1 on white. WCAG AA needs 4.5:1.","S","Ink 3 becomes #5F6B85 (4.94:1)","Fixed"),
       ("P0","A11y","Gain and loss on tinted chips and buttons","Gain green is 3.69:1 on its tint and 4.14:1 under white button text. Loss red is 4.08:1 on its tint.","S","Gain #06784A and loss #C42A32 (4.76 to 5.5:1)","Fixed"),
       ("P1","Visual","Buy pad, screen 05","The keypad shows only 1, 2, 3. The rest is clipped under the swipe bar.","S","Replace with a stepper and the system keyboard. Dock the swipe bar.","Fixed"),
       ("P1","A11y","Timeframe chips, tabs","Visual chips are about 28 pt tall. Tab labels are 11 px. Targets should be 44 pt.","M","Keep the visual, extend the hit area to 44 pt, raise captions to 12.5 px","Specified"),
       ("P1","Visual","Every price","Monospaced numerals read like code and flatten hierarchy.","S","Manrope 800 with tabular figures","Fixed"),
       ("P1","UX · H7","Active traders","No depth, baskets, bracket orders or margin view. Power users have to leave the app.","L","Flow G: eight trading tools","Fixed"),
       ("P1","UX · H1","Charts","No axes or scrub value, so exact prices cannot be read.","M","Add scrub tooltip and haptics (spec in motion). Build in dev.","Open"),
       ("P2","Visual","About a third of v1 screens","Content sits in the top half and the rest is empty, which feels unfinished.","M","Core screens and new flows are dense. Flows A to E got a content pass: orders, funds, reports, help, IPO and SIP screens gained the sections they lacked. Onboarding stays sparse on purpose, one question per screen.","Fixed"),
       ("P2","Visual","Accent colour","Lime is the selected tab, the primary button and banner tint. It is also invisible as text on light (1.08:1).","S","Ultramarine for action. Lime only on dark surfaces.","Fixed"),
       ("P2","UX · H10","Help and guidance","No first-trade guide, practice mode or glossary for new users.","M","H2, H3 and a glossary","Fixed"),
       ("P2","Motion","Whole app","No motion spec. Price changes, order confirmation and charts have no defined behaviour. Reduced motion unaddressed.","M","Eight demos and a spec table, each with a reduced-motion version","Fixed"),
       ("P2","UX · H9","System states","Only one rejection and one offline screen. No generic error, loading or maintenance pattern.","M","Error and empty patterns, skeleton, plus screens for the remaining states","Partly fixed"),
       ("P3","Visual","Components","Corner radii vary without a rule (cards, fields, chips).","S","Tokens: 16 fields, 22 cards, 99 pills","Fixed"),
       ("P3","Visual","Banner text","Olive text on lime tint was only legible by luck. Banner colours were hard-coded.","S","Banner tokens per intent, all above 4.5:1","Fixed")]
    kind={"Fixed":"up","Specified":"b","Open":"dn","Partly fixed":"w"}
    rows=[[f'<b>{p}</b>',cat,loc,iss,eff,fix,tag(st,kind[st])] for p,cat,loc,iss,eff,fix,st in F]
    worked=cards([("Signs and arrows beside colour","Gains show + and ▲, losses show − and ▼. Colour never carries meaning alone. Keep this."),("Swipe to confirm","A deliberate gesture prevents accidental orders without an extra dialog."),("Explicit order states","Waiting, filled and rejected are distinct, with next steps. A good pattern to copy."),("Tabular, right-aligned figures","Columns of prices line up and are easy to compare."),("Sentence-case buttons with verbs","Place bid, Start SIP. Clear and consistent.")],3)
    meta=f'<div class="chips" style="margin:0 0 14px"><span class="chip">Maturity: L0, greenfield (tokens defined in this pass)</span><span class="chip">Sub-agents: Visual, UX Critic, A11y, Motion</span><span class="chip">DS compliance: skipped (no design system yet)</span><span class="chip">{len(F)} findings · P0 2 · P1 5 · P2 5 · P3 2</span></div>'
    summary=note("<b>Summary.</b> v1 had a solid structure and good order states, but it failed contrast, hid its numbers in a code font and stopped short of what active traders and new investors need. The theme, type, structure and 33 new screens address all P0 and P1 items except chart scrubbing, which needs a build.","g")
    method=note("<b>Method.</b> This review used rendered screens and measured contrast, not an interactive prototype. Timing and gesture findings need a build to confirm. Review again after the first usability round.")
    return sec("13","review","Design review","The full review chain run on v1 (visual, UX heuristics, accessibility, motion), with status after v2.",meta+method+'<h3>What is working</h3>'+worked+'<h3>Findings</h3>'+tbl(["Sev","Area","Where","Issue","Effort","Fix","Status in v2"],rows)+summary)
# ───────── 14 gallery
def gallery():
    base=pathlib.Path(__file__).parent/"v2"
    files=[("core-v2.html","k","Core redesign","Home, markets, stock, order pad, portfolio, watchlist"),("screens.html","s","Original eight, re-themed","Sign in, buying, SIP and funds"),("flow-a-account.html","a","Flow A · Create an account","11 steps from welcome to ready"),("flow-b-markets.html","b","Flow B · Markets and research","Charts, options, advisory, learning"),("flow-c-orders.html","c","Flow C · Orders","Every order state"),("flow-d-portfolio.html","d","Flow D · Portfolio and products","Positions, funds, SIPs, IPOs"),("flow-e-account-system.html","e","Flow E · Account and system states","Funds, reports, settings, offline"),("flow-f-discover.html","f","Flow F · Discover and research · new","Movers, screener, depth, news, calendar"),("flow-g-trading-tools.html","g","Flow G · Advanced trading · new","Baskets, bracket, margin, strategy, pro chart"),("flow-h-trust-growth.html","h","Flow H · Trust and growth · new","Welcome, practice, tax, family, security, privacy")]
    out=''
    for fn,k,t,s in files:
        caps=re.findall(r'<div class="cap">(.*?)</div>',(base/fn).read_text())
        figs=''.join(f'<figure><img src="shots/{k}{i+1:02d}.png" alt="{esc(c)}" loading="lazy"><figcaption>{c}</figcaption></figure>' for i,c in enumerate(caps))
        out+=f'<h3>{t}</h3><p>{s}. {len(caps)} screens.</p><div class="shelf">{figs}</div>'
    return sec("14","screens","Every screen","All 92 screens in v2, in flow order.",out)
# ───────── 15 handoff
def handoff():
    stages=[("Discover","Feature audit and research plan written. Interviews to run.","Partly"),("Define","Problem statement, scope and metrics set.","Done"),("Structure","IA, flows, screen list and 12 wireframes.","Done"),("Test the wireframes","Test plan and tasks written. Needs participants.","Planned"),("Design system","Tokens, type, icons, components, motion and writing.","Done"),("Hi-fi screens","92 screens, including empty, offline and rejected states.","Done"),("Prototype","Motion demos built. Full clickable prototype to build.","Partly"),("Test the prototype","Test plan, tasks, metrics and SUS ready.","Planned"),("Handoff","This document: specs, events, states, changelog.","Done"),("Build","Developers with design on call.","Planned"),("Design QA","Review on staging, both themes, large text.","Planned"),("Launch and improve","Compare to baseline metrics, plan next round.","Planned")]
    k={"Done":"up","Partly":"w","Planned":"g"}
    st=tbl(["Stage","Where it stands","Status"],[[f'<b>{a}</b>',b,tag(c,k[c])] for a,b,c in stages])
    ev=tbl(["Event","When","Properties"],[["onboarding_started","Welcome opened","source"],["kyc_step_completed","Each account step","step"],["funds_added","Money credited","method, amount"],["watchlist_item_added","Stock added","symbol, list"],["stock_viewed","Stock detail opened","symbol, source"],["order_started","Order pad opened","symbol, side"],["order_reviewed","Total required shown","order_type, product"],["order_placed","Swipe completed","order_type, product, side"],["order_rejected","Exchange or risk reject","reason"],["order_filled","Fully filled","latency_ms"],["alert_created","Alert set","symbol, type"],["screener_run","Results shown","filter_count, result_count"],["basket_executed","Basket placed","leg_count"],["practice_mode_toggled","Switch changed","on"],["security_setting_changed","Setting changed","setting, on"],["report_downloaded","File downloaded","report_type"],["referral_shared","Link shared","channel"],["help_request_opened","Ticket created","topic"]])+'<p>Naming: lower snake case, object then action, past tense. No personal data in properties.</p>'
    states=tbl(["State","Covered by","Notes"],[["Empty","E8 and empty patterns","Every list has an empty state with one next step"],["Loading","Skeleton demo, motion spec","Rows keep shape, no spinner on full screens"],["Error and rejection","C6, error patterns","Reason in plain language plus a recovery action"],["Offline","E9","Last updated time shown, prices refresh when back"],["Long names and big numbers","Core and flow screens","Truncate with ellipsis, numbers never wrap, tested to ₹99,99,99,999"],["First-time user","H1, H2, H3","Guide fades after the first trade"],["Large text (200%)","H10","Layouts reflow, bars stack"],["Both themes","Tokens","Light and dark values defined and contrast-checked"],["Maintenance or market closed","G7, banners","Closed market offers an after-market order"]])
    nums=tbl(["Number worth knowing","Standard","Crestline v2"],[["Tap area, iOS","44 × 44 pt","Specified for every control"],["Tap area, Android","48 dp with 8 dp spacing","Specified"],["Target floor, WCAG 2.2","24 px","Exceeded"],["Body text contrast","4.5:1 (3:1 large)","All text pairs pass, computed above"]])
    notes='<ul class="l"><li><b>One source of truth.</b> Final frames carry a Ready for dev status. Drafts live on a separate page. The status does not lock a frame, so every later change goes in the changelog.</li><li><b>Screen IDs.</b> Every screen has an ID (A1, F5, G2). Use them in tickets and analytics.</li><li><b>Copy.</b> Final strings are in the screens. Manage them outside the design file.</li><li><b>Assets.</b> Icons as SVG, 24 px grid. Fonts: Manrope, open licence, with system fallback.</li></ul>'
    log=tbl(["Date","Change"],[["29 Oct 2026","v2 created: new tokens and type, Markets-first IA, 33 new screens, wireframes, motion, writing and review."],["29 Oct 2026","Screen titles set to title case. Contrast corrected on secondary text and gain and loss colours."]])
    return sec("15","handoff","Handoff","Where the work stands against the twelve stages, plus what developers need.",'<h3>Process tracker</h3>'+st+'<h3>Source of truth</h3>'+notes+'<h3>Analytics events</h3>'+ev+'<h3>States developers need</h3>'+states+'<h3>Standards</h3>'+nums+'<h3>Changelog</h3>'+log)
# ───────── 16 next
def nxt():
    ideas=cards([("Regional languages","Hindi, Marathi and Tamil first. Right-to-left is not needed, but text expands about 30%."),("Scrub with haptics","Touch the chart to read an exact price, with a light tick at each day."),("Order impact preview","Before confirming, show how the order changes margin and cash."),("Goal-based investing","Set a goal and a date, then suggest a monthly amount. Needs careful regulatory review."),("Recurring buys for stocks","Like SIPs, for people who want a steady habit."),("Tablet and web layout","Wider layouts for depth and charts for active traders.")],3)
    steps=tbl(["Next","Who","Outcome"],[["Run 5 to 8 interviews per persona","Designer and researcher","Real personas and a ranked list of problems"],["Test wireframes with 5 people per persona","Designer","Structure fixes before visual polish"],["Build the clickable prototype","Designer","Realistic tests of order and onboarding"],["Usability test and SUS","Researcher","Severity-ranked issues and a baseline score"],["Hand off and build","Team","Features on a staging build"],["Design QA and launch","Team","Compare metrics to baseline"]])
    return sec("16","next","Next steps and ideas","What to do after this document, and what to explore once the basics are validated.",'<h3>Next steps</h3>'+steps+'<h3>Ideas to explore</h3>'+ideas)
# ───────── assemble
SECTIONS=[("00","summary","Summary"),("01","brief","Brief and story"),("02","define","Define"),("03","research","Research plan"),("04","personas","Proto-personas"),("05","journey","Journey maps"),("06","ia","Information architecture"),("07","flows","User flows"),("08","gaps","Gap analysis"),("09","wireframes","Wireframes"),("10","system","Design system"),("11","motion","Motion"),("12","writing","UX writing"),("13","review","Design review"),("14","screens","Every screen"),("15","handoff","Handoff"),("16","next","Next steps")]
def build():
    toc='<nav class="toc" aria-label="Sections"><b>Crestline v2</b><small>Case study · concept</small>'+''.join(f'<a href="#{i}"><i>{n}</i>{t}</a>' for n,i,t in SECTIONS)+'<a href="../index.html" style="margin-top:18px;color:var(--brandInk)"><i>←</i>Back to showcase</a></nav>'
    body=hero()+summary()+brief()+define()+research()+personas()+journey()+ia()+flows()+gaps()+wires()+system()+motion()+writing()+review()+gallery()+handoff()+nxt()
    doc=(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Crestline v2 · Case Study</title>'
         '<meta name="description" content="A full case study for the Crestline trading app redesign: research plan, personas, flows, wireframes, design system, motion, writing, review and handoff.">'
         '<link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet">'
         f'<style>{CSS}</style></head><body><div class="shell">{toc}<main>{body}</main></div></body></html>')
    pathlib.Path(__file__).parent.joinpath("v2","case-study.html").write_text(doc)
    print("v2/case-study.html",len(doc)//1024,"KB")
if __name__=="__main__": build()
